#include <bits/stdc++.h>
using namespace std;

struct Rect {
    int x1, y1, x2, y2;
};

long long pointRectDist(int px, int py, const Rect& r) {
    long long dx = 0;
    if (px < r.x1) dx = r.x1 - px;
    else if (px > r.x2) dx = px - r.x2;
    long long dy = 0;
    if (py < r.y1) dy = r.y1 - py;
    else if (py > r.y2) dy = py - r.y2;
    return dx + dy;
}

long long rectDist(const Rect& a, const Rect& b) {
    long long dx = 0;
    if (a.x2 < b.x1) dx = b.x1 - a.x2;
    else if (b.x2 < a.x1) dx = a.x1 - b.x2;
    long long dy = 0;
    if (a.y2 < b.y1) dy = b.y1 - a.y2;
    else if (b.y2 < a.y1) dy = a.y1 - b.y2;
    return dx + dy;
}

struct DSU {
    vector<int> p, r;
    DSU(int n) {
        p.resize(n);
        r.resize(n, 0);
        iota(p.begin(), p.end(), 0);
    }
    int find(int x) {
        return p[x] == x ? x : p[x] = find(p[x]);
    }
    void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return;
        if (r[a] < r[b]) swap(a, b);
        p[b] = a;
        if (r[a] == r[b]) r[a]++;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int Xi, Yi, Xf, Yf;
    cin >> Xi >> Yi >> Xf >> Yf;
    int N;
    cin >> N;
    vector<Rect> rects(N);
    for (int i = 0; i < N; ++i) {
        cin >> rects[i].x1 >> rects[i].y1 >> rects[i].x2 >> rects[i].y2;
    }
    DSU dsu(N);
    for (int i = 0; i < N; ++i) {
        for (int j = i + 1; j < N; ++j) {
            if (max(rects[i].x1, rects[j].x1) <= min(rects[i].x2, rects[j].x2) &&
                max(rects[i].y1, rects[j].y1) <= min(rects[i].y2, rects[j].y2)) {
                dsu.unite(i, j);
            }
        }
    }
    vector<int> comp(N);
    int C = 0;
    unordered_map<int, int> rootToIdx;
    for (int i = 0; i < N; ++i) {
        int root = dsu.find(i);
        if (rootToIdx.find(root) == rootToIdx.end()) {
            rootToIdx[root] = C++;
        }
        comp[i] = rootToIdx[root];
    }
    const long long INF = 1e18;
    vector<long long> distS(C, INF), distT(C, INF);
    for (int i = 0; i < N; ++i) {
        int c = comp[i];
        long long dS = pointRectDist(Xi, Yi, rects[i]);
        if (dS < distS[c]) distS[c] = dS;
        long long dT = pointRectDist(Xf, Yf, rects[i]);
        if (dT < distT[c]) distT[c] = dT;
    }
    vector<vector<long long>> dist(C, vector<long long>(C, INF));
    for (int i = 0; i < N; ++i) {
        for (int j = i + 1; j < N; ++j) {
            int ci = comp[i], cj = comp[j];
            if (ci == cj) continue;
            long long d = rectDist(rects[i], rects[j]);
            if (d < dist[ci][cj]) {
                dist[ci][cj] = d;
                dist[cj][ci] = d;
            }
        }
    }
    int S_node = C;
    int T_node = C + 1;
    int total = C + 2;
    vector<long long> d(total, INF);
    d[S_node] = 0;
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;
    pq.push({0, S_node});
    while (!pq.empty()) {
        auto top = pq.top(); pq.pop();
        long long du = top.first;
        int u = top.second;
        if (du != d[u]) continue;
        if (u == T_node) break;
        if (u == S_node) {
            for (int i = 0; i < C; ++i) {
                long long w = distS[i];
                if (du + w < d[i]) {
                    d[i] = du + w;
                    pq.push({d[i], i});
                }
            }
            long long w = abs(Xi - Xf) + abs(Yi - Yf);
            if (du + w < d[T_node]) {
                d[T_node] = du + w;
                pq.push({d[T_node], T_node});
            }
        } else if (u == T_node) {
            // do nothing
        } else {
            for (int v = 0; v < C; ++v) {
                if (v == u) continue;
                long long w = dist[u][v];
                if (w < INF && du + w < d[v]) {
                    d[v] = du + w;
                    pq.push({d[v], v});
                }
            }
            long long w = distT[u];
            if (du + w < d[T_node]) {
                d[T_node] = du + w;
                pq.push({d[T_node], T_node});
            }
        }
    }
    cout << d[T_node] << "\n";
    return 0;
}
